SECRET = 'a3f9c1e0d2b7'
def check(guess):
    """Returns (ok, work). `work` = number of byte comparisons performed
    (a deterministic model of the wall-clock cost of a non constant-time compare)."""
    work = 0
    for i in range(min(len(guess), len(SECRET))):
        work += 1
        if guess[i] != SECRET[i]:
            return False, work
    if len(guess) == len(SECRET):
        work += 1
        return True, work
    return False, work
